    const FACTION_SCOPED_KEYS = [ "cat_enemy_faction_id", "cat_activation_cached", "cat_is_admin_cached", "cat_bs_access", "cat_calls_cache", "cat_cached_calls", "cat_online_statuses", "cat_hosp_times", "cat_travel_data", "cat_enemy_chain", "cat_has_active_war", "cat_war_score_target", "cat_attacking_signal", "cat_tactical_marker_signal", "cat_loadout_cache_war", "cat_faction_stats_cache" ];
    const FACTION_SCOPED_PREFIXES = [ "cat_calls_enabled_cached", "cat_ffs_faction_", "cat_ts_faction_", "cat_ffs_member_", "cat_ts_member_", "cat_activation_prompt_dismissed_", "cat_poll_leader_" ];
    const pendingWriteCancellers = [];
