        if (header && header.getAttribute("data-col") !== active) {
            setStatsHeaderCol(header, active);
            changed = true;
        }
        const hasBsp = !!scope.querySelector(".iconStats, .bsp-column");
        if (scope.classList.contains("no-bsp") === hasBsp) {
            scope.classList.toggle("no-bsp", !hasBsp);
            changed = true;
        }
        if (!scope.classList.contains("has-stats")) {
            scope.classList.add("has-stats");
            changed = true;
        }
